<script setup lang="ts">
import AttemptReport from '../components/AttemptReport.vue'
import { ref,computed,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import { usePlatform } from '../stores/platform'
import { candidateQuestions,seededShuffle } from '../domain/rules'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
const s=usePlatform(),route=useRoute(),router=useRouter();const page=computed(()=>String(route.params.page)),sessionId=computed(()=>String(route.query.session||'EXAM-001'));const activeSession=computed(()=>s.data.sessions.find(e=>e.id===sessionId.value));const attempt=computed(()=>s.data.attempts.find(a=>a.id===route.query.attempt&&a.candidate===s.actor));const qs=computed(()=>attempt.value?candidateQuestions(attempt.value.questions):[])
const index=ref(0),fontSize=ref(18),tick=ref(Date.now()),checked=ref(false),face=ref('待核验'),submitOpen=ref(false),signature=ref(''),calculator=ref(false),calcA=ref(0),calcB=ref(0),calcOp=ref('+'),expandedHelp=ref(0)
const pending=ref<Record<string,string[]>>({}),sequences=ref<Record<string,number>>({}),saveState=ref('已保存到本地演示存储'),textAnswer=ref('')
const current=computed(()=>qs.value[index.value]);const elapsed=computed(()=>attempt.value?Math.floor((tick.value-attempt.value.startedAt)/1000)+attempt.value.offset:0);const duration=computed(()=>s.data.sessions.find(e=>e.id===attempt.value?.sessionId)?.duration||90);const left=computed(()=>Math.max(0,duration.value*60-elapsed.value));const timeText=computed(()=>`${String(Math.floor(left.value/3600)).padStart(2,'0')}:${String(Math.floor(left.value%3600/60)).padStart(2,'0')}:${String(left.value%60).padStart(2,'0')}`)
const choices=computed(()=>current.value?seededShuffle(current.value.options.map((label,id)=>({label,id:String(id)})),current.value.id.split('').reduce((a,c)=>a+c.charCodeAt(0),0)):[])
const selectedAnswers=computed(()=>current.value?(pending.value[current.value.id]||attempt.value?.answers[current.value.id]||[]):[])
const person=computed(()=>s.data.protocol?.staff.find(p=>p.name===s.actor))
const enrollment=computed(()=>s.data.continuity!.enrollments.filter(e=>e.personId===s.personId))
const mySessions=computed(()=>s.data.sessions.filter(e=>enrollment.value.some(m=>m.sessionId===e.id)))
const ticket=(id:string)=>enrollment.value.find(e=>e.sessionId===id)?.ticket||'未列入名单'
const myAttempts=computed(()=>s.data.attempts.filter(a=>a.candidate===s.actor))
let timer:ReturnType<typeof setInterval>
function answer(values:string[]){if(!current.value||!attempt.value)return;const qid=current.value.id;pending.value[qid]=values;try{const seq=Math.max(sequences.value[qid]||0,attempt.value.seq[qid]||0)+1;sequences.value[qid]=seq;s.saveAnswer(attempt.value.id,qid,values,seq);delete pending.value[qid];saveState.value='已保存到本地演示存储'}catch(e){saveState.value='待同步 · '+(e instanceof Error?e.message:'保存失败')}}
function option(id:string){if(!current.value)return;const prev=selectedAnswers.value;if(current.value.type==='多选题')answer(prev.includes(id)?prev.filter(x=>x!==id):[...prev,id]);else answer([id])}
function retry(){if(!attempt.value)return;const a=attempt.value;Object.entries(pending.value).forEach(([qid,values])=>{try{const seq=Math.max(sequences.value[qid]||0,a.seq[qid]||0)+1;sequences.value[qid]=seq;s.saveAnswer(a.id,qid,values,seq);delete pending.value[qid]}catch(e){s.notify(e instanceof Error?e.message:'保存失败',true)}});saveState.value=Object.keys(pending.value).length?'仍有未同步答案':'已保存到本地演示存储'}
function begin(){s.run(()=>{if(!checked.value||face.value!=='模拟通过')throw new Error('请完成模拟核验并阅读考试须知');const id=s.startAttempt(sessionId.value);router.push({path:'/candidate/answer',query:{attempt:id}})})}
function submit(){s.run(()=>{if(Object.keys(pending.value).length)throw new Error('有未同步答案，请恢复保存并重试');s.submitAttempt(attempt.value!.id,signature.value);submitOpen.value=false;router.push('/candidate/reports')})}
function changeQuestion(i:number){index.value=i;textAnswer.value=(attempt.value?.answers[qs.value[i]!.id]||[]).join('')}
function onVisibility(){if(document.hidden&&attempt.value?.status==='在考')s.recordEvent(attempt.value.id,'浏览器离开考试页面（演示事件）')}
function beforeUnload(e:BeforeUnloadEvent){if(Object.keys(pending.value).length){e.preventDefault();e.returnValue=''}}
onBeforeRouteLeave(()=>{if(Object.keys(pending.value).length)return window.confirm('仍有未同步答案，离开将丢失这些修改。确定离开吗？')})
onMounted(()=>{timer=setInterval(()=>{tick.value=Date.now();if(page.value==='answer'&&attempt.value?.status==='在考'&&left.value<=0){retry();s.run(()=>{s.submitAttempt(attempt.value!.id,'到时自动交卷',true);router.replace('/candidate/reports')})}},1000);document.addEventListener('visibilitychange',onVisibility);window.addEventListener('beforeunload',beforeUnload)})
onUnmounted(()=>{clearInterval(timer);document.removeEventListener('visibilitychange',onVisibility);window.removeEventListener('beforeunload',beforeUnload)})
const help=[['如何进入考试？','从“我的考试”进入考前检查，完成模拟身份核验并阅读须知，即可开始作答。'],['作答如何保存？','选择答案后立即保存到当前浏览器。出现待同步提示时应恢复模拟网络并点击重试。未同步答案仅在当前页面内存中，离开会丢失。'],['能否刷新后继续作答？','同一浏览器的已保存答案、固定题序、标记和开始时间会恢复。该演示不承诺跨设备或真实服务器故障恢复。'],['什么时候可以交卷？','开考15分钟内禁止提前交卷。演示时可以点击“推进16分钟”操作，无需等待实际时间。'],['为什么成绩还未发布？','包含主观题时需先完成专家阅卷；存在分差的答卷还需仲裁。核定成绩由管理人员发布。'],['人脸与防舞弊是真实的吗？','本Demo仅模拟核验结果并记录浏览器失焦事件，没有连接真实人脸、公安、摄像头或系统级防舞弊服务。']]
</script>
<template>
<template v-if="page==='exams'"><PageHead title="我的考试" subtitle="查看考试安排，完成考前准备，在规定时间内参加认定。" eyebrow="考生中心 / 考试安排"/><Empty v-if="!mySessions.length" title="暂无分配的考试" description="考务人员添加本场名单后，考试安排会显示在此处。"/><div class="exam-cards"><article v-for="e in mySessions" class="panel exam-card"><div class="exam-card-top"><span class="exam-icon"><Icon name="ClipboardPenLine" :size="29"/></span><Badge :text="myAttempts.find(a=>a.sessionId===e.id)?.status||e.status"/></div><h2>{{e.name}}</h2><p class="muted">航空发动机装配工 · 三级 / 高级工 · 合成场次</p><div class="exam-info"><p><Icon name="CalendarDays" :size="17"/><span>考试安排</span><strong>{{e.date.replace('T',' ')}}</strong></p><p><Icon name="MapPin" :size="17"/><span>考点考场</span><strong>{{e.venue}} · {{e.room}}</strong></p><p><Icon name="Clock3" :size="17"/><span>考试时长</span><strong>{{e.duration}} 分钟</strong></p></div><div class="exam-card-bottom"><span>准考证：{{ticket(e.id)}}</span><button v-if="!myAttempts.find(a=>a.sessionId===e.id)" class="button primary" :disabled="!e.paperId" @click="router.push({path:'/candidate/check',query:{session:e.id}})">{{e.paperId?'进入考前检查':'等待配发试卷'}}<Icon name="ArrowRight" :size="16"/></button><button v-else-if="myAttempts.find(a=>a.sessionId===e.id)?.status==='在考'" class="button primary" @click="router.push({path:'/candidate/answer',query:{attempt:myAttempts.find(a=>a.sessionId===e.id)!.id}})">继续考试</button><button v-else class="button" @click="router.push('/candidate/reports')">查看结果</button></div></article></div><div class="notice spaced">演示场次使用独立时钟；显示日期为合成排期。已保存答案保留在当前浏览器，重置演示后清除。</div></template>
<template v-else-if="page==='check'"><PageHead title="考前检查" subtitle="核对个人信息与考试规则，确保作答前准备就绪。" eyebrow="我的考试 / 考前准备"><RouterLink class="button" to="/candidate/exams">返回考试列表</RouterLink></PageHead><div class="check-layout"><section class="panel check-main"><div class="panel-head"><h3>{{activeSession?.name}}</h3></div><div class="profile-summary"><span class="avatar large">演</span><div><h3>{{s.actor}}</h3><p>准考证号 {{ticket(sessionId)}} · {{s.person.org}}</p></div><Badge text="模拟考生"/></div><div class="precheck-row"><span class="icon-circle blue"><Icon name="UserRoundCheck"/></span><div><strong>身份核验</strong><p>使用模拟结果演示核验通过与失败流程，不采集人脸。</p></div><Badge :text="face"/><button class="button small" @click="face=face==='模拟通过'?'模拟失败':'模拟通过'">{{face==='模拟通过'?'模拟失败':'模拟核验'}}</button></div><div class="precheck-row"><span class="icon-circle teal"><Icon name="MonitorCheck"/></span><div><strong>作答环境</strong><p>当前浏览器本地演示 · 无真实IP锁定或系统级防舞弊。</p></div><Badge text="演示可用"/></div><div class="notice">当前模拟策略：IP {{s.data.protocol?.policy.ipRange}}；考中核验 {{s.data.protocol?.policy.faceDuring?'每'+s.data.protocol.policy.faceInterval+'分钟':'关闭'}}。仅展示配置，不执行真实安全拦截。</div><div class="notice warning">迟到超过30分钟不得入场，开考15分钟内不得提前交卷。请关注答题保存状态。</div><label class="checkbox-label"><input type="checkbox" v-model="checked"/>我已阅读考试须知，知晓当前为模拟演示环境。</label><button class="button primary large" :disabled="!checked||face!=='模拟通过'" @click="begin">确认并开始考试 <Icon name="ArrowRight" :size="17"/></button></section><section class="panel"><div class="panel-head"><h3>考试须知</h3></div><div class="aside-copy"><p v-for="(t,i) in ['请独立作答，遵守考试纪律。','选择题点击选项后自动保存。','可标记试题并通过答题卡快速定位。','保存失败时请重试，避免丢失未同步答案。','提交答卷前需再次确认并填写签名。']">{{i+1}}. {{t}}</p></div></section></div></template>
<template v-else-if="page==='answer'&&attempt&&current"><div class="answer-header"><div><span class="eyebrow">理论考试 / 本地模拟作答</span><h1>{{s.data.sessions.find(e=>e.id===attempt!.sessionId)?.name}}</h1><p>{{s.actor}} · 准考证 {{attempt.ticket}} <span class="save-indicator" :class="{pending:Object.keys(pending).length}"><Icon :name="Object.keys(pending).length?'CloudOff':'CloudCheck'" :size="16"/>{{saveState}}</span></p></div><div class="exam-clock"><Icon name="Timer" :size="28"/><div><span>剩余时间</span><strong>{{timeText}}</strong></div></div></div>
<div class="exam-demo-bar"><span><Icon name="FlaskConical" :size="15"/>演示控制</span><button @click="s.advanceTime(attempt.id)">推进16分钟</button><label><input type="checkbox" v-model="s.failSave"/>模拟保存失败</label><button v-if="Object.keys(pending).length" @click="retry">重试未同步答案</button><span class="push-right">核验与监考为模拟 · {{attempt.status}}</span></div>
<div class="answer-layout"><section class="panel answer-panel"><div class="answer-question-head"><Badge :text="current.type"/><span>第 <b>{{index+1}}</b> / {{qs.length}} 题 · {{current.score}} 分</span><div class="push-right"><button class="icon-button" aria-label="缩小字号" @click="fontSize=Math.max(16,fontSize-1)"><Icon name="Minus" :size="16"/></button><span>{{fontSize}}</span><button class="icon-button" aria-label="增大字号" @click="fontSize=Math.min(26,fontSize+1)"><Icon name="Plus" :size="16"/></button></div></div><div class="answer-body" :style="{fontSize:fontSize+'px'}"><h2>{{index+1}}. {{current.title}}</h2><div v-if="['单选题','多选题','判断题'].includes(current.type)" class="answer-options"><button v-for="(o,i) in choices" :key="o.id" :class="{chosen:selectedAnswers.includes(o.id)}" @click="option(o.id)" :disabled="attempt.status!=='在考'"><span class="choice-circle" :class="{square:current.type==='多选题'}"><Icon v-if="selectedAnswers.includes(o.id)" name="Check" :size="17"/></span><b>{{String.fromCharCode(65+i)}}.</b>{{o.label}}</button></div><label v-else class="field">请填写您的答案<textarea :value="selectedAnswers.join('')" @input="answer([($event.target as HTMLTextAreaElement).value])" rows="10" placeholder="在此填写作答内容…"/></label></div><div class="answer-bottom"><button class="button" :disabled="index===0" @click="changeQuestion(index-1)"><Icon name="ChevronLeft" :size="16"/>上一题</button><button class="button primary" :disabled="index===qs.length-1" @click="changeQuestion(index+1)">下一题<Icon name="ChevronRight" :size="16"/></button><button class="button push-right" @click="s.toggleMark(attempt.id,current.id)"><Icon name="Bookmark" :size="16"/>{{attempt.marked.includes(current.id)?'取消标记':'标记本题'}}</button><button class="button" @click="calculator=true"><Icon name="Calculator" :size="17"/></button></div></section><aside><section class="panel answer-card"><div class="panel-head"><h3>答题卡</h3><strong>{{Object.values(attempt.answers).filter(a=>a.length).length}} / {{qs.length}}</strong></div><div class="answer-legend"><span><i></i>未答</span><span><i class="filled"></i>已答</span><span><Icon name="Bookmark" :size="12"/>标记</span></div><div class="answer-grid"><button v-for="(q,i) in qs" :key="q.id" :class="{done:!!attempt.answers[q.id]?.length,current:index===i,marked:attempt.marked.includes(q.id)}" @click="changeQuestion(i)">{{i+1}}<i v-if="attempt.marked.includes(q.id)"></i></button></div><button class="button primary full" @click="submitOpen=true"><Icon name="Send" :size="17"/>提交答卷</button></section><section class="panel spaced"><div class="panel-head"><h3>作答提示</h3></div><div class="aside-copy"><p>多选题支持多个选项；演示判分规则为全部选对得分，错选、漏选不得分。</p><p>刷新页面会恢复已保存答案。未同步答案请先重试成功再离开。</p><p>交卷后不可修改答卷。</p></div></section></aside></div></template>
<template v-else-if="page==='reports'"><PageHead title="我的成绩报告" subtitle="查看作答结果、成绩状态与知识点得分分布。" eyebrow="考生中心 / 学习反馈"/><Empty v-if="!myAttempts.length" title="暂无考试记录" description="先参加一场演示考试，提交后即可查看结果。"><RouterLink class="button primary" to="/candidate/exams">查看我的考试</RouterLink></Empty><section v-for="a in myAttempts" class="panel result-report"><div class="panel-head"><h3>{{s.data.sessions.find(e=>e.id===a.sessionId)?.name}}</h3><Badge :text="a.status"/></div><div class="report-summary"><div class="score-ring"><strong>{{a.status==='在考'?'—':a.published?a.objective+(a.subjective||0):a.objective}}</strong><span>{{a.published?'已发布总分':'客观题已判分'}}</span></div><div><h2>{{a.status==='在考'?'考试进行中':a.published?'成绩已发布':a.status==='待阅卷'?'等待专家评阅':'答卷已提交'}}</h2><p>已答 {{Object.values(a.answers).filter(x=>x.length).length}} / {{a.questions.length}} 题 · {{a.submittedAt||'尚未交卷'}}</p><p class="muted">{{a.published?'正式演示成绩已核定并发布。':'最终成绩需由管理人员发布；当前仅展示已判部分。'}}</p></div></div><AttemptReport v-if="a.status!=='在考'" :attempt="a"/></section></template>
<template v-else-if="page==='profile'"><PageHead title="个人信息" subtitle="统一身份信息由集团人力资源系统提供，当前为合成档案。"/><section class="panel profile-card"><div class="profile-summary"><span class="avatar huge">演</span><div><h2>{{s.actor}}</h2><p>{{s.person.org}}</p><Badge text="模拟身份已建立"/></div></div><div class="detail-grid"><div v-for="row in [['人员编码',person?.id||'DEMO-0001'],['职业工种',person?.profession||'航空发动机装配工'],['当前等级',person?.level||'三级 / 高级工'],['申报等级','三级 / 高级工'],['考试名单',enrollment.length+'个场次'],['数据来源',person?.source||'本地合成']]"><span>{{row[0]}}</span><strong>{{row[1]}}</strong></div></div><div class="notice">身份信息不在考生端自行修改，实际变更通过主数据系统同步。</div></section></template>
<template v-else-if="page==='help'"><PageHead title="考试帮助" subtitle="了解考试流程、保存机制和成绩发布规则。"/><section class="panel help-list"><div v-for="(h,i) in help"><button @click="expandedHelp=expandedHelp===i?-1:i"><strong>0{{i+1}}　{{h[0]}}</strong><Icon :name="expandedHelp===i?'Minus':'Plus'" :size="18"/></button><p v-if="expandedHelp===i">{{h[1]}}</p></div></section></template>
<Empty v-else title="未找到对应答卷" description="请从我的考试中重新进入。"><RouterLink class="button primary" to="/candidate/exams">返回我的考试</RouterLink></Empty>
<Modal v-if="submitOpen&&attempt" title="确认提交答卷" @close="submitOpen=false"><div class="submit-count"><strong>{{Object.values(attempt.answers).filter(a=>a.length).length}}</strong><span>/ {{qs.length}}题已作答</span></div><div class="notice warning">{{Object.values(attempt.answers).filter(a=>a.length).length<qs.length?'仍有未作答试题。':''}}提交后不能修改，请确认已检查答卷。</div><label class="field">考生确认签名（演示文本签名）<input v-model="signature" placeholder="请输入签名，确认本人提交"/></label><p class="muted">此签名仅演示留痕，不是经过认证的电子签名。</p><template #footer><button class="button" @click="submitOpen=false">返回检查</button><button class="button primary" @click="submit">确认交卷</button></template></Modal>
<Modal v-if="calculator" title="基础计算器" @close="calculator=false"><div class="calculator"><input v-model.number="calcA" type="number" aria-label="第一个数"/><select v-model="calcOp"><option>+</option><option>-</option><option>×</option><option>÷</option></select><input v-model.number="calcB" type="number" aria-label="第二个数"/><strong>= {{calcOp==='+'?calcA+calcB:calcOp==='-'?calcA-calcB:calcOp==='×'?calcA*calcB:calcB===0?'除数不能为0':calcA/calcB}}</strong></div></Modal>
</template>
